ers->where('last_status','down')->count() }}</h4></div></div></div></div><div class="card"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>Device</th><th>Type</th><th>Notification</th><th>Status</th><th>Last Check</th><th>Latency</th><th>Actions</th></tr></thead><tbody>@forelse($watchers as $w)<tr><td><strong>{{ $w->name }}</strong><br><small>{{ $w->host }}:{{ $w->port }}</small></td><td>{{ $w->router_name ?: 'Device' }}</td><td>{{ $w->enabled ? 'Enabled' : 'Disabled' }}</td><td><span class="badge {{ $w->last_status==='online'?'bg-success':($w->last_status==='down'?'bg-danger':'bg-secondary') }}">{{ $w->last_status ?: 'Unknown' }}</span></td><td>{{ optional($w->last_checked_at)->format('d M H:i:s') ?: 'Never' }}</td><td>{{ $w->last_latency_ms !== null ? $w->last_latency_ms.' ms' : '—' }}</td><td><button class="btn btn-sm btn-outline-success" wire:click="check({{ $w->id }})">Check</button> <button class="btn btn-sm btn-outline-primary" wire:click="edit({{ $w->id }})">Edit</button> <button class="btn btn-sm btn-outline-danger" wire:click="delete({{ $w->id }})">Delete</button></td></tr>@empty<tr><td colspan="7" class="text-center py-5">No watcher found.</td></tr>@endforelse</tbody></table></div></div></div>